use std::collections::HashMap;

fn score_of(scores: &HashMap<&str, i32>, name: &str) -> i32 {
    scores.get(name).copied().unwrap_or(0)
}

fn main() {
    let mut scores = HashMap::new();
    scores.insert("a", 3);
    println!("{}", score_of(&scores, "b"));
}

