        Err(e) => println!("{e}"),
    }
}

use std::fmt;

struct Point {
    x: i32,
    y: i32,
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

fn main() {
    println!("{}", Point { x: 2, y: 3 });
}

fn evens_plus_one(nums: &[i32]) -> Vec<i32> {
    nums.iter()
        .filter(|n| *n % 2 == 0)
        .map(|n| n + 1)
        .collect()
}

fn main() {
    println!("{:?}", evens_plus_one(&[1, 2, 3, 4]));
}

use std::collections::HashMap;

fn tally(words: &[&str]) -> HashMap<String, u32> {
    let mut counts = HashMap::new();
    for word in words {
        *counts.entry((*word).to_string()).or_insert(0) += 1;
    }
    counts
}

fn main() {
    let map = tally(&["be", "to", "be"]);
    println!("{}", map["be"]);
}

enum Token {
    Ident(String),
    Number(i32),
    Eof,
}

fn describe(token: &Token) -> String {
    match token {
        Token::Ident(name) => format!("id {name}"),
        Token::Number(n) => format!("num {n}"),
        Token::Eof => String::from("eof"),
    }
}

fn main() {
    println!("{}", describe(&Token::Number(7)));
}

